const { generateSpeech } = require("ai");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
// Headerless 8-bit samples, as a provider returns for raw mu-law / A-law output.
const raw = new Uint8Array(64).fill(0x7f);
function model(format) {
  return {
    specificationVersion: "v4", provider: "mock", modelId: "mock-tts",
    async doGenerate(opts) {
      if (opts.outputFormat !== format) broken("outputFormat not passed to model: " + opts.outputFormat);
      return { audio: raw, warnings: [], response: { timestamp: new Date(), modelId: "mock-tts", headers: {} } };
    },
  };
}
(async () => {
  const got = {};
  for (const [format, want] of [["mulaw", "audio/mulaw"], ["alaw", "audio/alaw"]]) {
    let r;
    try { r = await generateSpeech({ model: model(format), text: "hi", outputFormat: format }); }
    catch (e) { broken("generateSpeech threw: " + e.message); }
    got[format] = r.audio.mediaType;
    if (got[format] !== want && got[format] !== "audio/mp3") broken("unexpected mediaType for " + format + ": " + got[format]);
  }
  if (got.mulaw === "audio/mp3" || got.alaw === "audio/mp3") symptom("headerless mu-law/A-law audio from generateSpeech is labeled audio/mp3");
  console.log("OK: mulaw -> " + got.mulaw + ", alaw -> " + got.alaw);
})().catch(e => broken(String(e && e.stack || e)));

